use strict;
use Path::Class::File;
use Carp();
use parent qw(Path::Class::Entity);
use IO::Dir ();
use File::Path ();
use File::Temp ();
use Scalar::Util ();

# --- METRICS ---
# line_count: 12
# cyclomatic_complexity: 1
# max_nesting_depth: 3

# --- HINTS ---
# method_chain: need: $condition->($_)
# method_chain: need: $self->children
# method_chain: need: $self->$callback
# method_chain: need: $_->traverse_if
# --- FUNCTION: traverse_if ---
sub traverse_if {
  my $self = shift;
  my ($callback, $condition, @args) = @_;
  my @children = grep { $condition->($_) } $self->children;
  return $self->$callback(
    sub {
      my @inner_args = @_;
      return map { $_->traverse_if($callback, $condition, @inner_args) } @children;
    },
    @args
  );
}

